@section('js')
<script>
$(function () {
 const table=$('#usersTable').DataTable({processing:true,serverSide:true,searchDelay:350,ajax:"{{ route('users.index', [], false) }}",columns:[{data:'photo',orderable:false,searchable:false},{data:'name',name:'name'},{data:'dni',name:'dni'},{data:'email',name:'email'},{data:'phone',name:'phone'},{data:'type',name:'user_type_label'},{data:'status',name:'is_active'},{data:'updated_at',name:'updated_at'},{data:'actions',orderable:false,searchable:false}],language:{search:'Buscar:',lengthMenu:'Mostrar _MENU_ registros',info:'Mostrando _START_ a _END_ de _TOTAL_ registros',infoEmpty:'Mostrando 0 a 0 registros',infoFiltered:'(filtrado de _MAX_ registros)',zeroRecords:'No se encontraron usuarios',emptyTable:'Aún no hay usuarios registrados',paginate:{first:'Primero',previous:'Anterior',next:'Siguiente',last:'Último'}}});
 const modalEl=document.getElementById('usersModal'), modal=bootstrap.Modal.getOrCreateInstance(modalEl), delModal=bootstrap.Modal.getOrCreateInstance(document.getElementById('usersDeleteModal'));
 const notice=(msg,kind='success')=>$('#usersNotice').html(`<div class="alert alert-${kind}">${$('<div>').text(msg).html()}</div>`);
 $(document).on('click','[data-user-modal]',function(){const url=this.dataset.userModal;$.ajax({url,headers:{'X-Modal-Request':'1'}}).done(html=>{modalEl.querySelector('.modal-content').innerHTML=html;modal.show()}).fail(()=>notice('No se pudo cargar el formulario. Inténtelo nuevamente.','danger'))});
 let delUrl='';$(document).on('click','[data-user-delete]',function(){delUrl=this.dataset.userDelete;delModal.show()});
 let labelUrl='';const labelModal=bootstrap.Modal.getOrCreateInstance(document.getElementById('classificationLabelModal'));$(document).on('click','[data-classification-label]',function(){labelUrl=this.dataset.classificationLabel;$('#classificationLabelInput').val(this.dataset.currentLabel);labelModal.show()});$('#classificationLabelForm').on('submit',function(e){e.preventDefault();$.ajax({url:labelUrl,method:'PATCH',data:{user_type_label:$('#classificationLabelInput').val(),_token:$('meta[name="csrf-token"]').attr('content')},headers:{'Accept':'application/json'}}).done(r=>{labelModal.hide();table.ajax.reload(null,false);notice(r.message)}).fail(x=>notice(x.responseJSON?.message||'No se pudo actualizar la clasificación.','danger'))});
 $('#confirmUserDelete').on('click',function(){ $.ajax({url:delUrl,method:'DELETE',headers:{'X-CSRF-TOKEN':$('meta[name="csrf-token"]').attr('content'),'X-Requested-With':'XMLHttpRequest'}}).done(r=>{delModal.hide();table.ajax.reload(null,false);notice(r.mensaje||r.message||'El usuario se eliminó correctamente.')}).fail(x=>notice(x.responseJSON?.message||x.responseJSON?.mensaje||'No se pudo eliminar el usuario.','danger')) });
 $(document).on('change','#usersModal #user_change_password',function(){const field=document.getElementById('user_password');field.disabled=!this.checked;if(!this.checked)field.value=''});
 $(document).on('submit','#usersModal .js-modal-form',function(e){e.preventDefault();const form=this,fd=new FormData(form);form.querySelectorAll('.is-invalid').forEach(x=>x.classList.remove('is-invalid'));form.querySelectorAll('.invalid-feedback').forEach(x=>x.remove());$.ajax({url:form.action,method:'POST',data:fd,processData:false,contentType:false,headers:{'X-Requested-With':'XMLHttpRequest','Accept':'application/json'}}).done(r=>{modal.hide();table.ajax.reload(null,false);notice(r.message||'Los cambios se guardaron correctamente.')}).fail(x=>{const errors=x.responseJSON?.errors||{};const password=form.querySelector('[name="password"]');if(password)password.value='';Object.entries(errors).forEach(([key,msgs])=>{const input=form.querySelector(`[name="${key}"]`);if(input){input.classList.add('is-invalid');const err=document.createElement('div');err.className='invalid-feedback d-block';err.textContent=msgs[0];input.after(err)}});if(!Object.keys(errors).length)notice(x.responseJSON?.message||'No se pudo guardar. Inténtelo nuevamente.','danger')})});
});
</script>
@stop
